	private static StackTraceElement[] awaitFrontierBarrier(Thread worker) {
		long deadline = System.nanoTime() + TimeUnit.SECONDS.toNanos(15);
		StackTraceElement[] stack = new StackTraceElement[0];
		while (worker.isAlive() && System.nanoTime() < deadline) {
			stack = worker.getStackTrace();
			boolean frontier = false;
			boolean admission = false;
			boolean barrier = false;
			for (StackTraceElement frame : stack) {
				frontier |= frame.getMethodName().equals("initializeFrontierStatisticsAfterReady");
				admission |= frame.getMethodName().equals("admitFrontierReaders");
				barrier |= frame.getClassName().equals(TxnManager.class.getName())
						&& frame.getMethodName().equals("acquireReadBarrier");
			}
			if (frontier && admission && barrier) {
				return stack;
			}
			Thread.onSpinWait();
		}
		throw new AssertionError("Frontier worker did not reach the held native read barrier: " + List.of(stack));
	}

	private static void awaitGate(CountDownLatch gate, String name) {
		try {
			if (!gate.await(60, TimeUnit.SECONDS)) {
				throw new IllegalStateException("fixture did not release " + name);
			}
		} catch (InterruptedException interrupted) {
			Thread.currentThread().interrupt();
			throw new IllegalStateException("fixture interrupted at " + name, interrupted);
		}
	}
